const results = await Promise.allSettled([
  tools.exec_command({cmd:"sed -n '270,560p' openlibrary/core/vendors.py",workdir:"/app",max_output_tokens:10000}),
  tools.exec_command({cmd:"sed -n '340,780p' openlibrary/tests/core/test_vendors.py",workdir:"/app",max_output_tokens:12000}),
  tools.exec_command({cmd:"find . -maxdepth 2 \\( -name 'pyproject.toml' -o -name 'pytest.ini' -o -name 'Makefile' -o -name 'setup.cfg' \\) -print",workdir:"/app",max_output_tokens:3000})
]); results.forEach((r,i)=>text(`RESULT ${i}\n${r.status==="fulfilled"?r.value.output:String(r.reason)}`));

const results = await Promise.allSettled([
  tools.exec_command({cmd:"git diff -- openlibrary/core/vendors.py",workdir:"/app",max_output_tokens:4000}),
  tools.exec_command({cmd:"grep -nE '^\\[tool\\.(pytest|ruff|black)|^test:|pytest' pyproject.toml Makefile | head -90",workdir:"/app",max_output_tokens:3000}),
  tools.exec_command({cmd:"find . -maxdepth 2 -name 'AGENTS.md' -o -name 'CONTRIBUTING.md' | head -30",workdir:"/app",max_output_tokens:1000})
]); results.forEach((r,i)=>text(`RESULT ${i}\n${r.status==="fulfilled"?r.value.output:String(r.reason)}`));

const results = await Promise.allSettled([
  tools.exec_command({cmd:"pytest openlibrary/tests/core/test_vendors.py -q",workdir:"/app",yield_time_ms:30000,max_output_tokens:5000}),
  tools.exec_command({cmd:"ruff check openlibrary/core/vendors.py openlibrary/tests/core/test_vendors.py",workdir:"/app",yield_time_ms:30000,max_output_tokens:2000}),
  tools.exec_command({cmd:"git diff --check && git status --short",workdir:"/app",yield_time_ms:30000,max_output_tokens:2000})
]); results.forEach((r,i)=>text(`RESULT ${i}\n${r.status==="fulfilled"?r.value.output + `\nexit=${r.value.exit_code}`:String(r.reason)}`));
